def item(subject, qno, page, topic, question, options, variant=None, stimulus=None):
    sid = "cbse25-26-" + {"business_studies":"bs", "english_core":"eng"}.get(subject, subject[:3])
    return {"item_id": f"{sid}-q{qno}" + (f"-{variant}" if variant else ""), "subject":subject, "topic_family":topic,
            "source_id":f"cbse-2025-26-{subject.replace('_','-')}-sqp", "question_no":str(qno), "paper_page":page,
            "question":question, "options":[{"label":chr(65+i),"text":x} for i,x in enumerate(options)],
            **({"stimulus_id":stimulus} if stimulus else {}), "source_status":"CBSE_sample_paper_candidate_not_CUET_PYQ"}

items=[]; gold=[]; stimuli=[]
def add(x, answer, key_locator, key_text, notes=""):
    items.append(x)
    gold.append({"item_id":x["item_id"], "official_answer_label":answer, "official_answer_text":next(o["text"] for o in x["options"] if o["label"]==answer),
                 "official_key_source_id":x["source_id"].replace("-sqp","-marking-scheme"), "official_key_locator":key_locator,
                 "official_key_text":key_text, "answer_provenance":"CBSE official marking scheme; key letter and option text cross-checked against printed SQP options", "notes":notes})

