def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
manifest={"schema":"cbse-2025-26-source-manifest-v1","acquisition_date":"2026-10-08","index_url":"https://cbseacademic.nic.in/SQP_CLASSXII_2025-26.html","reuse_rights":"No explicit redistribution license was verified. Retain PDFs and question excerpts for private audit only; do not redistribute source papers or present derived cases as official CUET questions.","english_passage_clustering":"Eight English candidates derive from two adapted passage roots (four items each), not eight independent passage roots.","source_authentication":"Official CBSE Academic website index links directly to these SQP and marking-scheme PDFs.","papers":[],"syllabus_scope":"Use the separate official CUET 2026 subject syllabus records in the baseline registry as the current available syllabus proxy; 2027 syllabus entitlement has not been verified here.","registered_source_collision_audit":"Metadata-only scan of the existing source registry found no records for these four 2025-26 CBSE SQP/marking-scheme source families before candidate construction.","candidate_item_count":len(items),"candidate_status":"not independently reviewed, not benchmark positives, not release eligible"}
